:root{--color-primary:#1b8168;--color-on-primary:#fff;--color-primary-soft:#dcf5ec;--color-focus-ring:#1b8168;
--color-accent-soft:#eaf2ce;--color-accent-fg:#56701f;--color-cream:#f4f8f0;--color-stage:#edf1ea;--color-line:#e2eadf;
--color-line-strong:#cbdac7;--color-paper:#fff;--color-ink:#1e2e27;--color-ink-soft:#5c7069;--color-danger:#b23b3b;
--color-danger-soft:#f6e4e2;--color-scrim:rgb(20 28 24/.55);--color-mint:#1b8168;--color-mint-soft:#d8f0e6;
--font-serif:"Bricolage Grotesque","Segoe UI",system-ui,sans-serif;--font-sans:"Figtree","Segoe UI",system-ui,sans-serif}
body{background:var(--color-stage-wide,#e7ede4)}
.stage{font-family:var(--font-sans);color:var(--color-ink);display:flex;gap:28px;flex-wrap:wrap;justify-content:center;padding:24px 12px}
.col{display:flex;flex-direction:column;align-items:center;gap:8px}
.cap{font:600 12px var(--font-sans);color:var(--color-ink-soft);max-width:390px;text-align:center}
.phone{position:relative;width:390px;height:760px;background:var(--color-stage);border-radius:36px;border:8px solid #1e2e27;overflow:hidden;display:flex;flex-direction:column}
.scroll{flex:1;overflow-y:auto}
.hdr{padding:18px 18px 4px}
.eyebrow{font-size:11px;font-weight:800;letter-spacing:.08em;text-transform:uppercase;color:var(--color-primary)}
.back{font-size:12px;font-weight:700;color:var(--color-ink-soft);margin-bottom:10px;display:inline-block}
h1.t{font:600 24px var(--font-serif);margin:2px 0}
.sub{font-size:12.5px;color:var(--color-ink-soft)}
.card{border-radius:24px;border:1px solid var(--color-line);background:var(--color-paper);padding:16px;margin:18px 18px 24px}
.card h2{font-size:17px;margin:0 0 4px;font-family:var(--font-serif)}
.body{font-size:13px;color:var(--color-ink-soft);line-height:1.45;margin:6px 0 0}
.btn-primary{border-radius:999px;border:0;background:var(--color-primary);color:var(--color-on-primary);font-weight:800;padding:7px 14px;font-size:12px;cursor:pointer}
.btn-primary.lg{padding:10px 14px;font-size:13px}
.btn-primary[disabled]{opacity:.6}
.btn-ghost{border-radius:999px;border:1.5px solid var(--color-line);background:transparent;font-weight:700;color:var(--color-ink-soft);padding:7px 14px;font-size:12px}
.btn-ghost.lg{padding:10px 14px;font-size:13px}
.auth-links{display:flex;gap:8px;margin-top:12px}
.hint-code{margin-top:10px;font-size:12px;font-weight:700;color:var(--color-primary-fg,#117b63);background:var(--color-primary-soft);border-radius:12px;padding:8px 10px}
.scrim{position:absolute;inset:0;background:var(--color-scrim);display:flex;align-items:flex-end;justify-content:center}
.sheet{width:100%;background:var(--color-paper);border-radius:24px 24px 0 0;padding:20px}
.sheet-h{display:flex;align-items:center;justify-content:space-between;margin-bottom:16px}
.sheet-h h3{font:600 18px var(--font-serif);margin:0}
.x{width:36px;height:36px;border-radius:999px;background:var(--color-cream);border:0;color:var(--color-ink-soft);font-size:16px}
label.lbl{display:block;font-size:12.5px;font-weight:700;margin-bottom:6px}
.field{width:100%;box-sizing:border-box;border-radius:12px;border:1.5px solid var(--color-line);background:var(--color-cream);padding:10px 12px;font:600 20px ui-monospace,Consolas,monospace;letter-spacing:.18em;color:var(--color-ink)}
.field.focus{border-color:var(--color-focus-ring);box-shadow:0 0 0 3px var(--color-primary-soft)}
.field.invalid{border-color:var(--color-danger)}
.hint{font-size:11.5px;color:var(--color-ink-soft);margin-top:5px}
.err{font-size:12px;color:var(--color-danger);margin-top:8px;font-weight:600}
.actions{display:flex;gap:8px;margin-top:16px}
.actions>*{flex:1}
.states{display:grid;grid-template-columns:repeat(2,1fr);gap:10px;padding:14px;background:var(--color-paper);border-radius:16px;max-width:820px}
.state{border:1px dashed var(--color-line-strong);border-radius:14px;padding:12px}
.state .tag{font-size:10.5px;font-weight:800;text-transform:uppercase;color:var(--color-ink-soft);margin-bottom:8px;letter-spacing:.06em}
/* panel */
.p-scroll{flex:1;overflow-y:auto;padding:18px 18px 24px;background:var(--color-paper)}
.p-h2{font-size:19px;font-weight:600;margin:0}
.dl{margin-top:16px;border-radius:16px;border:1px solid var(--color-line);background:var(--color-cream);padding:15px}
.dl .row{display:flex;justify-content:space-between;gap:12px;padding:4px 0}
.dl dt{font-size:12.5px;color:var(--color-ink-soft)} .dl dd{margin:0;font-size:13px;font-weight:600;text-align:right}
.link-mint{font-size:12.5px;font-weight:700;color:var(--color-mint);margin-top:8px;display:inline-block}
.jcc{margin-top:16px;border-radius:16px;border:1px solid var(--color-line);background:var(--color-paper);padding:15px}
.jcc h3{font:700 15px var(--font-serif);margin:0}
.jcc .lead{font-size:12px;color:var(--color-ink-soft);margin:3px 0 10px}
.code{font:700 30px ui-monospace,Consolas,monospace;letter-spacing:.14em;background:var(--color-mint-soft);color:#12604D;border-radius:14px;text-align:center;padding:10px 0}
.jcc .btns{display:flex;flex-direction:column;gap:8px;margin-top:12px}
.p-primary{border-radius:13px;background:var(--color-mint);color:#fff;border:0;padding:11px 16px;font-size:13.5px;font-weight:800;display:flex;align-items:center;justify-content:center;gap:6px}
.p-secondary{border-radius:13px;border:1.5px solid var(--color-line);background:var(--color-paper);color:var(--color-ink-soft);padding:11px 16px;font-size:13.5px;font-weight:800;display:flex;align-items:center;justify-content:center;gap:6px}
.p-text{background:none;border:0;color:var(--color-ink-soft);font-size:12.5px;font-weight:700;text-decoration:underline;padding:6px;align-self:center}
.toast{position:absolute;left:50%;bottom:78px;transform:translateX(-50%);background:var(--color-ink);color:#eaf2e9;font-size:12.5px;font-weight:700;padding:8px 14px;border-radius:999px;white-space:nowrap}
.h3{margin:24px 0 0;font:700 17px var(--font-serif)}
.member{margin-top:10px;border-radius:16px;border:1px solid var(--color-line);background:var(--color-cream);padding:15px;display:flex;justify-content:space-between}
.pill{border-radius:999px;background:var(--color-mint-soft);color:#12604D;font-size:10.5px;font-weight:800;padding:2px 10px;height:fit-content}
.nav{height:62px;border-top:1px solid var(--color-line);background:var(--color-paper);display:flex;justify-content:space-around;align-items:center;font-size:11px;color:var(--color-ink-soft);font-weight:700}
.alert{position:absolute;inset:0;background:var(--color-scrim);display:flex;align-items:center;justify-content:center;padding:16px}
.alert .box{width:100%;max-width:340px;border-radius:24px;background:var(--color-paper);padding:20px}
.alert h2{font:600 18px var(--font-serif);margin:0}
.alert p{font-size:14px;color:var(--color-ink-soft);margin:8px 0 0}
.alert .row{display:flex;gap:10px;margin-top:20px}
.alert .row button{flex:1;min-height:44px;border-radius:999px;font-size:14px;font-weight:800}
.b-cancel{border:1.5px solid var(--color-line);background:var(--color-cream);color:var(--color-ink)}
.b-confirm{border:0;background:var(--color-primary);color:var(--color-paper)}
.panel-sheet{width:100%;background:var(--color-paper);border-radius:24px 24px 0 0;padding:20px;max-height:92%;overflow-y:auto;box-sizing:border-box}
.cta{margin-top:16px;border-radius:16px;background:var(--color-accent-soft);padding:14px;font-size:14px}
.cta a{display:inline-block;margin-top:8px;font-weight:800;color:var(--color-accent-fg)}
.dim{opacity:.35;pointer-events:none}

